class ConcatenatedOperationType(AbstractCoordinateOperationType):
    """
    gml:ConcatenatedOperation is an ordered sequence of two or more coordinate operations.

    This sequence of operations is constrained by the requirement that the source coordinate reference system of
    step (n+1) must be the same as the target coordinate reference system of step (n). The source coordinate
    reference system of the first step and the target coordinate reference system of the last step are the source
    and target coordinate reference system associated with the concatenated operation. Instead of a forward
    operation, an inverse operation may be used for one or more of the operation steps mentioned above, if the
    inverse operation is uniquely defined by the forward operation. The gml:coordOperation property elements are an
    ordered sequence of associations to the two or more operations used by this concatenated operation. The
    AggregationAttributeGroup should be used to specify that the coordOperation associations are ordered.
    """

    model_config = ConfigDict(defer_build=True)
    uses_operation: list[UsesOperation] = field(
        default_factory=list,
        metadata={
            "name": "usesOperation",
            "type": "Element",
            "namespace": "http://www.opengis.net/gml/3.2",
        },
    )
